    await tick();
    assert.ok(run(`__banco['daycare/banho-falta/${dia}/bol'].quem`) === 'Carla' && /JÁ FOI DECIDIDO/.test(run('__alertas[0].t')), '"ainda vem" sobre "ainda vem" não regrava');
