    run(`banhoFaltaPerguntar('${dia}');`);
    assert.ok(run('__esc.length') === 1 && run('__esc[0].b[2]') === 'Ainda vem', JSON.stringify(run('__esc')));
    run('__esc[0].fn[2]();'); await tick();
