    run('__esc[0].fn[1]();'); await tick();                     // «Ele está aqui»
    igual([run(`__banco['daycare/chamada/${dia}/${kP}']`), run(`__banco[banhoFaltaNo('${dia}')+'/${kP}'].decisao`)], ['veio', 'mantido']);
