    igual([run(`BANHO_FALTA_DEC['${kP}']===undefined`), run(`BANHO_FALTA_VISTO['${dia}|${kP}']===undefined`)], [true, true], 'a pergunta do banho volta');
    igual(run('__med629'), 1, 'o remédio relê a fila (voltou a faltar)');
