  const semTab = res36(dados36(cad36(OUT644(), { renov_hist: { a: hist644(Object.assign(JUL644(), { plano: 'Platina' }), 100) } })), '2026-07');
  igual([semTab.porFILHOt.length, semTab.semComoCalcular.length], [0, 1]);
