    assert.ok(/data-ch="rafael__rui-teste" data-dia="2026-10-09" onclick="banhoDiaHoraAbrir\(this\.dataset\.ch,this\.dataset\.dia\)">mudar a hora só este dia<\/button>/.test(h0), h0);
