    l = run('banhosLinhaHTML(PELUDINHOS[0])');
    assert.ok(/<option value="2026-10-23" selected>sex 23\/10 — pulado<\/option>/.test(l) && /onclick="banhosTirarExcecao\(this\.dataset\.ch,this\.dataset\.dia\)">Pôr de volta este dia</.test(l), l);
