      run("dashHoraAbrirOutro('banhosaida');");
      igual(run('__hr652'), 2);
      run("dashHoraEscolher('banho', '10:00');");
      igual(run('__hr652'), 2, 'o relógio do Banho não mexe no Hoje');
      // o ouvinte das estadias
      run('__hr652=0; __rdc652=0; banhoSaidaEstadiasMudaram();');
