    DIA652(TER652);
    run(`__est652('est_raf', Object.assign(__dbPega('auaulandia/estadias/est_raf'), {ficha:{banho:'Sim', alim:{tipo:'Ração'}, spa:{banho:'Sim', tipo:'', horario:'', aConfirmar:true}}, pertences:[]}));`);
