    igual(run('__tg659').map((m) => [m.grupo, m.texto]), [['vet', 'CANCELADO — Vacina de Raiva do Tico — tutor autorizou para 13/10/2026 (manhã) — o tutor mudou a resposta para "Não quer agora". Não precisa preparar.']]);
