  while (textos.length < 1000) { let t = ''; const n = Math.floor(rnd() * 140); for (let i = 0; i < n; i++) t += al[Math.floor(rnd() * al.length)]; textos.push(t); }
  ctx.__tx676 = textos;
  const meu = J676('__tx676.map(function(t){ return zSha256Hex(t); })');
