    igual([v.byQ['Vomitou?'], v.passou, vs.length, vs[0].byQ['Vomitou?'], vs[0].corrigida.motivo, vs[0].corrigida.registro.por, !!vs[0].versoes], ['Sim', 'Wandela Teste', 1, 'Não', MOT667, 'Wandela Teste', false]);
